describe('Long-Running Task Persistence Across Page Refreshes', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should persist long-running task state across page refreshes', () => {
    // Intercept the API call to start a long-running task
    cy.intercept('POST', '/api/tasks/start').as('startTask');

    // Verify initial page state
    cy.get('[data-testid="task-list"]').should('be.visible');
    cy.get('[data-testid="task-item"]').should('have.length.greaterThan', 0);

    // Start a long-running task
    cy.get('[data-testid="start-task-button"]').click();
    cy.wait('@startTask');

    // Verify task is in progress state
    cy.get('[data-testid="task-item"]').first().should('contain', 'In Progress');

    // Verify task details are displayed
    cy.get('[data-testid="task-name"]').should('contain', 'Long Running Task');
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');

    // Verify task ID is stored in local storage
    cy.window().then((win) => {
      expect(win.localStorage.getItem('taskId')).to.not.be.null;
    });

    // Refresh the page
    cy.reload();

    // Verify task persists after refresh
    cy.get('[data-testid="task-list"]').should('be.visible');
    cy.get('[data-testid="task-item"]').first().should('contain', 'In Progress');

    // Verify task ID is still stored in local storage
    cy.window().then((win) => {
      expect(win.localStorage.getItem('taskId')).to.not.be.null;
    });

    // Verify task details are still displayed
    cy.get('[data-testid="task-name"]').should('contain', 'Long Running Task');
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
  });

  it('should handle task state when page is refreshed with no task ID', () => {
    // Intercept the API call to start a long-running task
    cy.intercept('POST', '/api/tasks/start').as('startTask');

    // Start a long-running task
    cy.get('[data-testid="start-task-button"]').click();
    cy.wait('@startTask');

    // Verify task is in progress state
    cy.get('[data-testid="task-item"]').first().should('contain', 'In Progress');

    // Simulate page refresh without task ID
    cy.window().then((win) => {
      win.localStorage.removeItem('taskId');
    });

    // Verify task persists without ID
    cy.reload();

    // Verify task is still visible
    cy.get('[data-testid="task-list"]').should('be.visible');

    // Verify task details are still displayed
    cy.get('[data-testid="task-item"]').first().should('contain', 'In Progress');

    // Verify task ID is not stored in local storage
    cy.window().then((win) => {
      expect(win.localStorage.getItem('taskId')).to.be.null;
    });

    // Verify task is still in progress state
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
  });
});
